@import "tailwindcss" source(none);

@theme {
  --color-diesel: #1B1A17;     /* ink, type, the darkest slab */
  --color-limestone: #ECE7DC;  /* the page */
  --color-chalk: #F8F5EE;      /* cards, marking-paint outlines */
  --color-blade: #F2B31B;      /* machine yellow: the only accent, always a fill behind diesel type */
  --color-topsoil: #2F261E;    /* dark slabs: job log, footer */
  --color-clay: #9A4A2B;       /* rare secondary: errors, the live dot */
  --color-gravel: #6A645A;     /* muted text, hairlines */
  --color-locate: #1F5FA8;     /* locate-flag blue: water and pipe only */

  --font-plate: var(--font-sofia-condensed), "Arial Narrow", Impact, sans-serif;
  --font-work: var(--font-work-sans), system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-gauge: var(--font-b612-mono), ui-monospace, "SFMono-Regular", Consolas, monospace;

  /* weighted, like iron: things are pushed in sideways or dropped from above and settle a hair past level */
  --ease-out: cubic-bezier(0.2, 0.9, 0.25, 1);
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.7, 0, 0.2, 1);
  --ease-settle: linear(0, 0.5 10%, 0.92 22%, 1.05 32%, 1.01 46%, 0.995 60%, 1);

  --dur-instant: 90ms;
  --dur-fast: 160ms;
  --dur-base: 380ms;
  --dur-slow: 700ms;
  --dur-hero: 1100ms;

  --reveal-shift: 22px;
  --stagger: 60ms;
}

:root {
  --tv-gutter: clamp(18px, 4.6vw, 72px);
  --tv-max: 1360px;
  --tv-radius: 2px;
  --tv-level-h: 10px;
  --tv-bar-h: 64px;
  --tv-head: calc(var(--tv-level-h) + var(--tv-bar-h));
  --tv-progress: 0;
  --tv-hero: 0;
}

html { scroll-behavior: smooth; scroll-padding-top: 88px; }
@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } }
html.lenis, html.lenis body { height: auto; }
.lenis.lenis-smooth { scroll-behavior: auto !important; }
html.tv-locked { overflow: hidden; }

.tv-body {
  margin: 0;
  background: var(--color-limestone);
  color: var(--color-diesel);
  font-family: var(--font-work);
  font-size: clamp(1rem, 0.96rem + 0.2vw, 1.1rem);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overflow-x: clip;
}
.tv-body *, .tv-body *::before, .tv-body *::after { box-sizing: border-box; }
.tv-body ::selection { background: var(--color-blade); color: var(--color-diesel); }
:where(.tv-body) :is(h1, h2, h3, p, ul, ol, dl, dd, figure, fieldset, table) { margin: 0; padding: 0; }
:where(.tv-body) :is(ul, ol) { list-style: none; }
:where(.tv-body) fieldset { border: 0; min-width: 0; }
:where(.tv-body) a { color: inherit; text-decoration: none; }
:where(.tv-body) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
:where(.tv-body) picture { display: block; }
:where(.tv-body) img { display: block; max-width: 100%; height: auto; }
/* a diesel line inside a blade ring: visible on limestone, on the dark slabs and on yellow */
:where(.tv-body) :focus-visible { outline: 2px solid var(--color-diesel); outline-offset: 2px; box-shadow: 0 0 0 5px var(--color-blade); border-radius: var(--tv-radius); }

.tv-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.tv-skip { position: fixed; top: 16px; left: 10px; z-index: 90; padding: 10px 16px; background: var(--color-diesel); color: var(--color-blade); font: 800 1.2rem/1 var(--font-plate); text-transform: uppercase; letter-spacing: 0.04em; transform: translateY(-220%); }
.tv-skip:focus { transform: none; }
.tv-gauge { font-family: var(--font-gauge); font-size: 0.74rem; letter-spacing: 0.1em; text-transform: uppercase; line-height: 1.4; }
.tv-wrap { width: 100%; max-width: calc(var(--tv-max) + var(--tv-gutter) * 2); margin-inline: auto; padding-inline: var(--tv-gutter); }
.tv-placeholder { display: grid; place-items: center; min-height: 220px; background: color-mix(in srgb, var(--color-gravel) 22%, var(--color-limestone)); outline: 2px dashed var(--color-gravel); outline-offset: -10px; color: var(--color-diesel); }

/* ── Type ───────────────────────────────────────────── */
.tv-title { font: 900 clamp(3rem, 7.6vw, 7.25rem)/0.88 var(--font-plate); text-transform: uppercase; letter-spacing: 0.002em; text-wrap: balance; }
.tv-line { display: block; overflow: clip; padding-top: 0.06em; }
.tv-line > span { display: block; }
.tv-lede { font-size: clamp(1.1rem, 1rem + 0.5vw, 1.36rem); line-height: 1.45; max-width: 54ch; }
.tv-eyebrow { display: flex; align-items: center; gap: 10px; color: var(--color-gravel); }
.tv-eyebrow::before { content: ""; width: 10px; height: 10px; background: var(--color-blade); border: 1.5px solid var(--color-diesel); flex: none; }
.tv-eyebrow:has(.tv-flag, .tv-chip, .tv-live)::before { content: none; }
.tv-dark .tv-eyebrow { color: color-mix(in srgb, var(--color-limestone) 72%, transparent); }
.tv-dark .tv-eyebrow::before { border-color: var(--color-blade); }
.tv-blade-text { color: var(--color-blade); }
.tv-chip { width: 10px; height: 10px; background: var(--color-blade); border: 1.5px solid var(--color-diesel); flex: none; }
.tv-flag { width: 12px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; }
.tv-flag-cloth { fill: var(--color-locate); stroke: var(--color-locate); }
.tv-live { width: 9px; height: 9px; border-radius: 50%; background: var(--color-blade); flex: none; }

.tv-section { position: relative; padding-block: clamp(72px, 9.5vw, 148px) 0; }
.tv-head { display: grid; gap: clamp(14px, 1.6vw, 22px); margin-bottom: clamp(32px, 4.6vw, 64px); max-width: 980px; }
.tv-dark { background: var(--color-topsoil); color: var(--color-limestone); }
.tv-diesel { background: var(--color-diesel); }

/* ── Brand marks ────────────────────────────────────── */
.tv-logo { display: inline-flex; align-items: center; gap: 10px; }
.tv-mark { width: 38px; height: 38px; flex: none; }
.tv-mark-block { fill: var(--color-blade); }
.tv-logo-text { display: grid; line-height: 1; }
.tv-logo-word { font: 900 2.05rem/0.82 var(--font-plate); text-transform: uppercase; letter-spacing: 0.01em; }
.tv-logo-sub { font-size: 0.5rem; letter-spacing: 0.42em; font-weight: 700; margin-top: 3px; }
.tv-logo-link { display: inline-flex; }

.tv-ticket { display: inline-flex; align-items: center; gap: 8px; padding: 8px 11px 7px; border: 1.5px dashed currentColor; font-size: 0.7rem; white-space: nowrap; }
.tv-ticket svg { width: 12px; height: 12px; fill: none; stroke: var(--color-blade); stroke-width: 2.2; flex: none; }

.tv-hatch { display: block; height: 28px; margin-top: clamp(72px, 9.5vw, 148px); border-top: 2px solid currentColor; transform-origin: left; }
.tv-hatch-earth, .tv-footer-hatch { background: repeating-linear-gradient(135deg, transparent 0 9px, currentColor 9px 10.5px, transparent 10.5px 13px, currentColor 13px 14.5px, transparent 14.5px 17px, currentColor 17px 18.5px, transparent 18.5px 34px); }
.tv-hatch-gravel { background-image: radial-gradient(currentColor 1.3px, transparent 1.7px), radial-gradient(currentColor 2px, transparent 2.5px); background-size: 14px 13px, 23px 19px; background-position: 2px 3px, 9px 8px; }
.tv-hatch-rock { background: repeating-linear-gradient(90deg, transparent 0 38px, currentColor 38px 39.5px), repeating-linear-gradient(0deg, transparent 0 12.5px, currentColor 12.5px 14px); }

/* ── Buttons and links ──────────────────────────────── */
.tv-btn {
  --btn-bg: var(--color-blade); --btn-fg: var(--color-diesel); --btn-edge: var(--color-blade);
  --btn-wipe: var(--color-diesel); --btn-fg-on: var(--color-blade);
  position: relative; isolation: isolate; overflow: hidden; display: inline-flex; align-items: center; justify-content: center;
  padding: 17px 26px 15px; min-height: 54px; background: var(--btn-bg); color: var(--btn-fg); border: 2px solid var(--btn-edge);
  border-radius: var(--tv-radius); font: 800 1.42rem/1 var(--font-plate); letter-spacing: 0.035em; text-transform: uppercase; white-space: nowrap;
  transition: transform var(--dur-base) var(--ease-settle), color var(--dur-fast) var(--ease-out);
}
/* the fill is a blade pass: pushed across from the left */
.tv-btn::before { content: ""; position: absolute; inset: -1px; z-index: -1; background: var(--btn-wipe); transform: scaleX(0); transform-origin: left; transition: transform var(--dur-base) var(--ease-in-out); }
.tv-btn-label { position: relative; }
.tv-btn:active { transform: translateY(3px); transition-duration: var(--dur-instant); transition-timing-function: var(--ease-out); }
.tv-btn-small { padding: 11px 16px 9px; min-height: 42px; font-size: 1.16rem; }
.tv-btn-dark { --btn-bg: var(--color-diesel); --btn-fg: var(--color-limestone); --btn-edge: var(--color-diesel); --btn-wipe: var(--color-blade); --btn-fg-on: var(--color-diesel); }
.tv-btn-ghost { --btn-bg: transparent; --btn-fg: var(--color-limestone); --btn-edge: var(--color-limestone); --btn-wipe: var(--color-limestone); --btn-fg-on: var(--color-diesel); }
.tv-btn-onlight { --btn-fg: var(--color-diesel); --btn-edge: var(--color-diesel); --btn-wipe: var(--color-diesel); --btn-fg-on: var(--color-limestone); }
.tv-btn[aria-disabled="true"] { cursor: progress; }
.tv-magnet { display: inline-block; transform: translate(var(--tv-mx, 0px), var(--tv-my, 0px)); transition: transform var(--dur-base) var(--ease-settle); }
.tv-magnet[data-pulled="true"] { transition: transform 120ms var(--ease-out); }

.tv-link { background: linear-gradient(currentColor, currentColor) 100% 100% / 0% 1.5px no-repeat; transition: background-size var(--dur-base) var(--ease-in-out); padding-bottom: 2px; }

@media (hover: hover) and (pointer: fine) {
  .tv-btn:hover { color: var(--btn-fg-on); }
  .tv-btn:hover::before { transform: none; }
  /* draws in from the left, leaves to the right */
  .tv-link:hover { background-size: 100% 1.5px; background-position: 0 100%; }
}

/* ── Header ─────────────────────────────────────────── */
.tv-header { position: fixed; inset: 0 0 auto 0; z-index: 60; display: flex; flex-direction: column; pointer-events: none; }
.tv-level { order: -1; position: relative; z-index: 2; height: var(--tv-level-h); background: color-mix(in srgb, var(--color-blade) 82%, var(--color-chalk)); border-bottom: 1.5px solid var(--color-diesel); pointer-events: none; }
/* the two lines a bubble sits between when it is level: halfway down the page */
.tv-level::before, .tv-level::after { content: ""; position: absolute; top: 0; bottom: 0; width: 1.5px; background: var(--color-diesel); left: calc(50% - 21px); }
.tv-level::after { left: calc(50% + 20px); }
.tv-level-bubble { position: absolute; top: 1px; bottom: 1px; left: 0; width: 34px; background: var(--color-chalk); border: 1.5px solid var(--color-diesel); border-radius: 999px; transform: translateX(calc(var(--tv-progress) * (100vw - 34px))); }

.tv-bar { position: relative; z-index: 1; pointer-events: auto; display: flex; align-items: center; gap: clamp(12px, 2vw, 28px); height: var(--tv-bar-h); padding-inline: var(--tv-gutter); background: var(--color-limestone); border-bottom: 1.5px solid var(--color-diesel); transition: transform var(--dur-base) var(--ease-in-out); }
.tv-header[data-state="hidden"][data-menu="false"] .tv-bar { transform: translateY(-102%); pointer-events: none; }
.tv-bar .tv-logo { transform-origin: left center; transition: transform var(--dur-base) var(--ease-out); }
.tv-header:not([data-state="top"]) .tv-bar .tv-logo { transform: scale(0.9); }
.tv-nav { position: relative; margin-left: auto; display: none; }
.tv-nav ul { display: flex; gap: clamp(14px, 1.8vw, 28px); }
.tv-nav-link { display: block; padding: 12px 0; color: var(--color-diesel); transition: color var(--dur-fast) var(--ease-out); }
.tv-nav-link[aria-current="true"] { font-weight: 700; }
/* one marker that slides between links, instead of an underline per link */
.tv-nav-marker { position: absolute; left: 0; bottom: 4px; width: 1px; height: 3px; background: var(--color-blade); outline: 1px solid var(--color-diesel); transform-origin: left; transform: translateX(var(--tv-nav-x, 0px)) scaleX(var(--tv-nav-w, 0)); opacity: 0; transition: transform var(--dur-base) var(--ease-in-out), opacity var(--dur-fast) var(--ease-out); }
.tv-nav[data-active="true"] .tv-nav-marker { opacity: 1; }
.tv-phone { display: none; padding: 10px 12px 9px; background: var(--color-diesel); color: var(--color-blade); font-weight: 700; font-size: 0.78rem; border-radius: var(--tv-radius); transition: transform var(--dur-base) var(--ease-settle); }
.tv-phone:active { transform: translateY(2px); transition-duration: var(--dur-instant); }
.tv-header-cta { display: none; --btn-wipe: var(--color-diesel); --btn-edge: var(--color-diesel); }
.tv-menu-toggle { margin-left: auto; width: 46px; height: 46px; display: grid; place-items: center; border: 1.5px solid var(--color-diesel); border-radius: var(--tv-radius); background: var(--color-blade); }
.tv-menu-icon { display: grid; gap: 5px; width: 20px; }
.tv-menu-icon i { height: 2.5px; background: var(--color-diesel); transition: transform var(--dur-base) var(--ease-in-out), opacity var(--dur-fast) var(--ease-out); transform-origin: center; }
[aria-expanded="true"] > .tv-menu-icon i:nth-child(1) { transform: translateY(7.5px) rotate(45deg); }
[aria-expanded="true"] > .tv-menu-icon i:nth-child(2) { opacity: 0; transform: scaleX(0); }
[aria-expanded="true"] > .tv-menu-icon i:nth-child(3) { transform: translateY(-7.5px) rotate(-45deg); }

.tv-menu { position: fixed; inset: var(--tv-head) 0 0 0; z-index: 0; pointer-events: auto; display: flex; flex-direction: column; justify-content: space-between; gap: 24px; padding: 28px var(--tv-gutter) 32px; background: var(--color-diesel); color: var(--color-limestone); overflow-y: auto; visibility: hidden; clip-path: inset(0 0 0 100%); transition: clip-path var(--dur-slow) var(--ease-in-out), visibility 0s linear var(--dur-slow); }
.tv-menu[data-open="true"] { visibility: visible; clip-path: inset(0); transition-delay: 0s; }
.tv-menu-list { display: grid; }
.tv-menu-list a { display: flex; align-items: baseline; gap: 16px; padding: 10px 0; border-bottom: 1px solid color-mix(in srgb, var(--color-limestone) 22%, transparent); font: 900 clamp(2.8rem, 13vw, 4.4rem)/0.95 var(--font-plate); text-transform: uppercase; }
.tv-menu-list a .tv-gauge { color: var(--color-blade); }
.tv-menu-foot { display: grid; gap: 16px; justify-items: start; }
.tv-menu-phone { color: var(--color-blade); font-size: 1rem; font-weight: 700; padding: 6px 0; }
.tv-menu-list li, .tv-menu-foot { opacity: 0; transform: translateX(28px); transition: opacity var(--dur-base) var(--ease-out), transform var(--dur-slow) var(--ease-out); }
.tv-menu[data-open="true"] :is(.tv-menu-list li, .tv-menu-foot) { opacity: 1; transform: none; transition-delay: calc(140ms + var(--i) * var(--stagger)); }

@media (min-width: 620px) { .tv-phone { display: block; margin-left: auto; } .tv-menu-toggle { margin-left: 0; } }
@media (min-width: 1000px) {
  .tv-nav { display: block; }
  .tv-phone { margin-left: 0; }
  .tv-header-cta { display: inline-flex; }
  .tv-menu-toggle, .tv-menu { display: none; }
}
@media (hover: hover) and (pointer: fine) {
  .tv-nav-link:hover { color: var(--color-gravel); }
}

/* ── Hero ───────────────────────────────────────────── */
.tv-hero { position: relative; background: var(--color-diesel); color: var(--color-limestone); padding-top: var(--tv-head); overflow: clip; }
.tv-hero-bg { position: absolute; inset: var(--tv-head) 0 0 0; z-index: 0; overflow: hidden; background: var(--color-topsoil); }
.tv-hero-frame { width: 100%; height: 100%; overflow: hidden; background: var(--color-topsoil); }
.tv-hero-frame picture, .tv-hero-frame img { width: 100%; height: 100%; }
.tv-hero-frame img { object-fit: cover; object-position: 72% 48%; transform: translateY(calc(var(--tv-hero) * 4%)) scale(1.06); }
.tv-hero-scrim { position: absolute; inset: 0; z-index: 1; pointer-events: none; background: linear-gradient(180deg, color-mix(in srgb, var(--color-diesel) 82%, transparent) 0%, color-mix(in srgb, var(--color-diesel) 64%, transparent) 52%, color-mix(in srgb, var(--color-diesel) 86%, transparent) 100%); }
.tv-hero-inner { position: relative; z-index: 2; display: grid; gap: clamp(20px, 3vw, 40px); max-width: calc(var(--tv-max) + var(--tv-gutter) * 2); margin-inline: auto; padding: clamp(32px, 5vw, 72px) var(--tv-gutter) clamp(44px, 6vw, 76px); align-items: end; }
.tv-hero-copy { position: relative; display: grid; gap: clamp(16px, 1.8vw, 24px); justify-items: start; max-width: 620px; }
.tv-hero-eyebrow { color: var(--color-blade); }
.tv-hero-eyebrow::before { border-color: var(--color-blade); background: transparent; }
.tv-hero-title { font: 900 clamp(4.1rem, 17.5vw, 8rem)/0.84 var(--font-plate); text-transform: uppercase; letter-spacing: 0.002em; }
.tv-hero-lead { font-size: clamp(1.08rem, 1rem + 0.45vw, 1.32rem); line-height: 1.45; max-width: 44ch; color: color-mix(in srgb, var(--color-limestone) 92%, transparent); }
.tv-hero-actions { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 4px; }
.tv-hero-tickets { display: flex; flex-wrap: wrap; gap: 8px; }
.tv-hero-tag { justify-self: start; display: inline-flex; gap: 14px; padding: 9px 12px 8px; background: var(--color-blade); color: var(--color-diesel); font-size: 0.68rem; font-weight: 700; border-radius: var(--tv-radius); outline: 2px dashed color-mix(in srgb, var(--color-chalk) 70%, transparent); outline-offset: 4px; }
.tv-hero-tag span + span { font-weight: 400; }
.tv-grade { position: absolute; inset: auto 0 0 0; z-index: 2; height: 6px; background: var(--color-blade); transform-origin: left; }

@media (min-width: 1000px) {
  .tv-hero-scrim { background: linear-gradient(90deg, color-mix(in srgb, var(--color-diesel) 92%, transparent) 0%, color-mix(in srgb, var(--color-diesel) 76%, transparent) 40%, color-mix(in srgb, var(--color-diesel) 20%, transparent) 70%, transparent 100%); }
  .tv-hero-inner { grid-template-columns: minmax(0, 1fr) auto; min-height: clamp(580px, 56.25vw, min(860px, calc(100svh - 62px))); align-items: center; gap: clamp(32px, 4vw, 64px); }
  .tv-hero-title { font-size: clamp(4.4rem, 7.1vw, 7.6rem); white-space: nowrap; }
  .tv-hero-tag { align-self: end; justify-self: end; }
}

/* ── Ticker ─────────────────────────────────────────── */
.tv-ticker { background: var(--color-blade); color: var(--color-diesel); border-block: 2px solid var(--color-diesel); }
.tv-marquee { overflow: hidden; }
.tv-marquee-track { display: flex; width: max-content; }
.tv-marquee-set { display: flex; flex: none; }
.tv-ticker-item { display: inline-flex; align-items: center; gap: clamp(18px, 2.4vw, 34px); padding: 13px 0 10px clamp(18px, 2.4vw, 34px); font: 900 clamp(1.7rem, 3vw, 2.6rem)/1 var(--font-plate); text-transform: uppercase; white-space: nowrap; }
.tv-ticker-item i { width: 12px; height: 12px; background: var(--color-diesel); flex: none; }

/* ── The work: Cut / Fill / Pipe / Haul ─────────────── */
.tv-tabs { position: relative; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); border: 2px solid var(--color-diesel); background: var(--color-chalk); }
.tv-tab-marker { position: absolute; inset: 0 auto 0 0; width: 25%; background: var(--color-blade); transform: translateX(calc(var(--tv-tab) * 100%)); transition: transform var(--dur-slow) var(--ease-in-out); }
.tv-tab { position: relative; display: grid; gap: 2px; align-content: start; padding: clamp(10px, 1.6vw, 22px) clamp(8px, 1.6vw, 22px) clamp(8px, 1.3vw, 18px); border-left: 2px solid var(--color-diesel); transition: transform var(--dur-base) var(--ease-settle); }
.tv-tab:first-of-type { border-left: 0; }
.tv-tab:active { transform: translateY(2px); transition-duration: var(--dur-instant); }
.tv-tab-no { color: var(--color-gravel); font-size: 0.66rem; }
.tv-tab[aria-selected="true"] .tv-tab-no { color: var(--color-diesel); font-weight: 700; }
.tv-tab-name { font: 900 clamp(2.1rem, 6.4vw, 5.6rem)/0.86 var(--font-plate); text-transform: uppercase; }
.tv-tab-move { display: none; font-size: 0.66rem; color: var(--color-gravel); }
.tv-tab[aria-selected="true"] .tv-tab-move { color: var(--color-diesel); }
.tv-tab:focus-visible { z-index: 2; }

.tv-panels { display: grid; border: 2px solid var(--color-diesel); border-top: 0; background: var(--color-chalk); overflow: clip; }
.tv-panel { grid-area: 1 / 1; display: grid; gap: clamp(20px, 3vw, 44px); padding: clamp(16px, 2.6vw, 36px); align-items: start; }
.tv-panel:not([data-state="active"]) { visibility: hidden; opacity: 0; }
.tv-panel-photo { position: relative; align-self: stretch; }
.tv-panel-photo picture { overflow: hidden; height: 100%; min-height: 240px; background: var(--color-limestone); }
.tv-panel-photo img { width: 100%; height: 100%; object-fit: cover; aspect-ratio: 4 / 3; }
.tv-panel-photo figcaption { position: absolute; left: 0; bottom: 0; padding: 8px 11px 7px; background: var(--color-diesel); color: var(--color-limestone); font-size: 0.66rem; }
.tv-panel-copy { display: grid; gap: clamp(12px, 1.4vw, 18px); justify-items: start; }
.tv-panel-verb { font: 900 clamp(2.8rem, 5.4vw, 5rem)/0.88 var(--font-plate); text-transform: uppercase; }
.tv-panel-blurb { max-width: 50ch; }
.tv-services { width: 100%; border-top: 2px solid var(--color-diesel); margin-block: 6px 10px; }
.tv-services li { display: grid; gap: 2px 20px; padding: 11px 0 10px; border-bottom: 1px solid color-mix(in srgb, var(--color-gravel) 45%, transparent); }
