.tv-estimate-copy { display: grid; gap: clamp(14px, 1.6vw, 22px); }
.tv-contact { display: grid; gap: 0; border-top: 2px solid var(--color-diesel); margin-top: 8px; }
.tv-contact > div { display: grid; grid-template-columns: 96px 1fr; gap: 14px; padding: 12px 0 11px; border-bottom: 1px solid color-mix(in srgb, var(--color-gravel) 45%, transparent); align-items: baseline; }
.tv-contact dt { color: var(--color-gravel); }
.tv-contact-big { font: 900 clamp(2.2rem, 4vw, 3.2rem)/0.9 var(--font-plate); }
.tv-locate { display: flex; gap: 12px; align-items: flex-start; padding: 14px 16px; border: 1.5px dashed var(--color-locate); font-size: 0.96rem; max-width: 52ch; }
