.tv-form-shell { position: relative; display: grid; background: var(--color-chalk); border: 2px solid var(--color-diesel); border-radius: var(--tv-radius); box-shadow: 10px 10px 0 var(--color-diesel); }
.tv-form, .tv-done { grid-area: 1 / 1; }
.tv-form { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px 14px; padding: clamp(18px, 2.6vw, 34px); transition: clip-path var(--dur-slow) var(--ease-in-out), opacity var(--dur-base) var(--ease-out); clip-path: inset(0); }
