.tv-kind input { position: absolute; inset: 0; opacity: 0; cursor: pointer; }
.tv-kind span { display: block; padding: 11px 15px 8px; min-height: 44px; border: 1.5px solid var(--color-diesel); border-radius: var(--tv-radius); font: 800 1.3rem/1.1 var(--font-plate); text-transform: uppercase; letter-spacing: 0.03em; transition: transform var(--dur-base) var(--ease-settle), background-color var(--dur-fast) var(--ease-out); }
