.tv-kind input:focus-visible + span { outline: 2px solid var(--color-diesel); outline-offset: 2px; box-shadow: 0 0 0 5px var(--color-blade); }
.tv-field input, .tv-field textarea { width: 100%; padding: 13px 13px 12px; background: var(--color-limestone); border: 1.5px solid var(--color-gravel); border-radius: var(--tv-radius); font: inherit; color: var(--color-diesel); transition: border-color var(--dur-fast) var(--ease-out), background-color var(--dur-fast) var(--ease-out); }
.tv-field textarea { resize: vertical; min-height: 112px; }
