@media (min-width: 1000px) { .tv-estimate-grid { grid-template-columns: minmax(0, 0.9fr) minmax(0, 1fr); } }

/* ── Footer ─────────────────────────────────────────── */
.tv-footer { position: relative; padding-bottom: 28px; overflow: clip; }
