.tv-footer-big { font: 900 clamp(3rem, 7.6vw, 7.25rem)/0.88 var(--font-plate); text-transform: uppercase; letter-spacing: 0.002em; text-wrap: balance; color: color-mix(in srgb, var(--color-blade) 92%, var(--color-topsoil)); margin: clamp(36px, 5vw, 72px) 0 clamp(28px, 4vw, 56px); }
