@media (min-width: 800px) { .tv-footer-grid { grid-template-columns: 1.3fr 0.7fr 1fr; } }

/* ── Hover and pointer effects (fine pointers only) ─── */
@media (hover: hover) and (pointer: fine) {
  .tv-tab:not([aria-selected="true"]):hover .tv-tab-name { transform: translateY(-3px); }
  .tv-tab-name { transition: transform var(--dur-base) var(--ease-out); }
  .tv-filter:not([aria-pressed="true"]):hover { border-color: var(--color-blade); color: var(--color-blade); }
  .tv-job-open:hover { transform: translateY(-6px); }
  .tv-job-open:hover .tv-job-photo img { transform: scale(1.06); }
  /* the rest of the log steps back while one ticket is lifted */
  .tv-log-grid:has(.tv-job-open:hover) .tv-job-open:not(:hover) { opacity: 0.5; }
  .tv-key:hover { background: var(--color-limestone); color: var(--color-diesel); }
  .tv-key-close:hover { background: var(--color-chalk); border-color: var(--color-chalk); }
