  .tv-yard-photo:hover img, .tv-about-photo:hover img { transform: scale(1.05); }
}

/* ── Motion: everything below only runs when motion is welcome ── */
@keyframes tv-marquee { to { transform: translateX(-50%); } }
@keyframes tv-rise-line { from { transform: translateY(110%); } }
@keyframes tv-rise { from { opacity: 0; transform: translateY(var(--reveal-shift)); } }
@keyframes tv-slide { from { opacity: 0; transform: translateX(-22px); } }
@keyframes tv-drop { from { opacity: 0; transform: translateY(-34px); } }
@keyframes tv-draw { from { transform: scaleX(0); } }
@keyframes tv-push { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0); } }
@keyframes tv-bar-drop { from { opacity: 0; transform: translateY(-14px); } }
@keyframes tv-shake-a { 20% { transform: translateX(-6px); } 45% { transform: translateX(6px); } 70% { transform: translateX(-3px); } }
@keyframes tv-shake-b { 20% { transform: translateX(-6px); } 45% { transform: translateX(6px); } 70% { transform: translateX(-3px); } }
@keyframes tv-pulse { 50% { opacity: 0.25; } }

@media (prefers-reduced-motion: no-preference) {
  /* reveals: the hidden state only exists here, so reduced-motion and no-JS visitors see everything */
  [data-reveal] { transition: opacity var(--dur-base) var(--ease-out), transform var(--dur-slow) var(--ease-out), clip-path var(--dur-slow) var(--ease-in-out); transition-delay: calc(var(--delay, 0ms) + var(--i, 0) * var(--stagger)); }
  [data-reveal="rise"]:not([data-in="true"]) { opacity: 0; transform: translateY(var(--reveal-shift)); }
