  [data-reveal="drop"] { transition-timing-function: var(--ease-out), var(--ease-settle), var(--ease-in-out); }
  [data-reveal="drop"]:not([data-in="true"]) { opacity: 0; transform: translateY(-34px); }
  [data-reveal="draw"]:not([data-in="true"]) { transform: scaleX(0); }
  /* the wipe clips the children, never the observed element: a fully clipped target would not intersect */
  [data-reveal="push"] > * { clip-path: inset(0); transition: clip-path var(--dur-slow) var(--ease-in-out); transition-delay: inherit; }
  [data-reveal="push"]:not([data-in="true"]) > * { clip-path: inset(0 100% 0 0); }
  [data-reveal="push"] img { transition: transform 1200ms var(--ease-out); transition-delay: inherit; }
  [data-reveal="push"]:not([data-in="true"]) img { transform: scale(1.14); }
  [data-reveal="lines"] { transition: none; }
  [data-reveal="lines"] .tv-line > span { transition: transform var(--dur-slow) var(--ease-out-expo); transition-delay: calc(var(--delay, 0ms) + var(--l, 0) * 90ms); }
  [data-reveal="lines"] .tv-line:nth-of-type(2) > span { --l: 1; }
  [data-reveal="lines"]:not([data-in="true"]) .tv-line > span { transform: translateY(110%); }

  /* hero load sequence: CSS keyframes, so it plays before hydration */
  .tv-bar > * { animation: tv-bar-drop var(--dur-base) var(--ease-settle) both; }
  .tv-bar > :nth-child(1) { animation-delay: 150ms; }
  .tv-bar > :nth-child(2) { animation-delay: 200ms; }
  .tv-bar > :nth-child(3) { animation-delay: 250ms; }
  .tv-bar > :nth-child(4) { animation-delay: 300ms; }
  .tv-bar > :nth-child(5) { animation-delay: 300ms; }
  .tv-hero-eyebrow { animation: tv-slide var(--dur-slow) var(--ease-out) 200ms both; }
  .tv-hero-title .tv-line > span { animation: tv-rise-line var(--dur-slow) var(--ease-out-expo) 250ms both; }
  .tv-hero-title .tv-line:nth-of-type(2) > span { animation-delay: 340ms; }
  .tv-hero-lead { animation: tv-rise var(--dur-slow) var(--ease-out) 600ms both; }
  .tv-hero-actions { animation: tv-rise var(--dur-slow) var(--ease-out) 700ms both; }
  .tv-hero-tickets li { animation: tv-drop var(--dur-base) var(--ease-settle) 820ms both; }
  .tv-hero-tickets li:nth-child(2) { animation-delay: 900ms; }
  .tv-hero-tag { animation: tv-drop var(--dur-base) var(--ease-settle) 980ms both; }
  .tv-grade { animation: tv-draw var(--dur-hero) var(--ease-in-out) 900ms both; }

  /* ambient: the ticker and the hiring dot, both paused off screen */
  .tv-marquee-track { animation: tv-marquee 46s linear infinite; animation-play-state: paused; }
  .tv-marquee[data-running="true"] .tv-marquee-track { animation-play-state: running; }
  .tv-live { animation: tv-pulse 2.4s var(--ease-in-out) infinite; }

  /* work panels: the old one is pushed out to the left, the new one comes in from the right */
  .tv-panel { transition: transform var(--dur-slow) var(--ease-in-out), opacity var(--dur-base) var(--ease-out), visibility 0s linear var(--dur-slow); }
  .tv-panel[data-state="active"] { transition-delay: 0s; }
  .tv-panel[data-state="before"] { transform: translateX(-7%); }
  .tv-panel[data-state="after"] { transform: translateX(7%); }

  .tv-panel-photo picture { clip-path: inset(0 100% 0 0); transition: clip-path var(--dur-slow) var(--ease-in-out) 80ms; }
  .tv-panel[data-state="active"] .tv-panel-photo picture { clip-path: inset(0); }
  .tv-services li { opacity: 0; transform: translateY(12px); transition: opacity var(--dur-base) var(--ease-out), transform var(--dur-base) var(--ease-out); }
  .tv-panel[data-state="active"] .tv-services li { opacity: 1; transform: none; transition-delay: calc(160ms + var(--i) * 45ms); }

  /* job log: after a filter change the matching tickets drop back in */
  .tv-log-grid[data-filtered="true"] .tv-job { animation: tv-drop var(--dur-base) var(--ease-settle) var(--d, 0ms) both; }
  .tv-viewer[open] .tv-viewer-card { animation: tv-drop var(--dur-base) var(--ease-settle) both; }
  .tv-viewer-photo img { animation: tv-push var(--dur-slow) var(--ease-in-out) both; }

  /* form: invalid fields shake once, the sent ticket drops in */
  .tv-field[data-shake="0"] { animation: tv-shake-a 280ms var(--ease-out); }
  .tv-field[data-shake="1"] { animation: tv-shake-b 280ms var(--ease-out); }
  .tv-form-shell[data-status="sent"] .tv-done > * { animation: tv-drop var(--dur-base) var(--ease-settle) both; animation-delay: calc(260ms + var(--n, 0) * 70ms); }
  .tv-done > :nth-child(2) { --n: 1; }
  .tv-done > :nth-child(3) { --n: 2; }
  .tv-done > :nth-child(4) { --n: 3; }
  .tv-done > :nth-child(5) { --n: 4; }
}

@media (hover: hover) and (pointer: fine) {
  .tv-marquee:hover .tv-marquee-track { animation-play-state: paused; }
}

@media (prefers-reduced-motion: reduce) {
  .tv-body *, .tv-body *::before, .tv-body *::after { transition-duration: 1ms !important; transition-delay: 0ms !important; animation: none !important; }
  .tv-hero-frame img { transform: none; }
  .tv-magnet { transform: none; }
}

